package session

import (
	"context"
	"fmt"
)

// Redis is the subset of the Redis client the store uses.
type Redis interface {
	Expire(ctx context.Context, key string, ttlSeconds int64) (bool, error)
	PExpire(ctx context.Context, key string, ttlMillis int64) (bool, error)
}

// Store keeps sessions in Redis.
type Store struct {
	redis Redis
}

// Touch extends a session's life by ttlMillis milliseconds.
func (s *Store) Touch(ctx context.Context, id string, ttlMillis int64) error {
	if ttlMillis <= 0 {
		return fmt.Errorf("session: touch %s: non-positive ttl", id)
	}
	if _, err := s.redis.PExpire(ctx, "session:"+id, ttlMillis); err != nil {
		return fmt.Errorf("session: touch %s: %w", id, err)
	}
	return nil
}
